/** Proper display name for an affiliate key ("golf-pride-mcc-plus4" -> "Golf Pride MCC Plus4"). */
export function productName(key: string): string {
  if (PRODUCT_DISPLAY[key]) return PRODUCT_DISPLAY[key];
  return key.split('-').map(t => /^\d/.test(t) ? t.toUpperCase() : t[0].toUpperCase()+t.slice(1)).join(' ');
}
